<script setup lang="ts">
import Pagination from '../../shared/components/Pagination.vue'
import FormDialog from '../../shared/components/FormDialog.vue'
import {ref} from 'vue'

const {can}=useWorkspace()
import { formatTimestamp } from '../../shared/time'
import { useWorkspace } from '../../app/workspace'
import CustodyPanel from './CustodyPanel.vue'
const { inventory, evidence, viewEvents, loading, evidencePage, evidenceTotal, moveEvidence, selectedItem, events, eventPage, eventTotal, moveEvents, makeSample, sampleLabel, sampleWeight, sampleReason, searchCases, search, casePage, caseTotal, moveCase, makeEvidence, evidenceCase, cases, label, weight, reason } = useWorkspace()
const { observations, total: inventoryTotal, page: inventoryPage, observedWeight, note: inventoryNote, move: moveInventory, submit: submitInventory, selectedObservation, investigation, investigationPage, investigationNote, showInvestigation, moveInvestigation, startInvestigation, transitionInvestigation } = inventory
const {error}=useWorkspace()
const creating=ref(false)
async function submitCreate(){if(await makeEvidence())creating.value=false}
</script>

<template>
<div class="page-list"><section class="card"><div class="page-toolbar page-toolbar-actions"><button v-if="can('evidence.write')" type="button" :disabled="loading" @click="error='';creating=true">登记证物</button></div><div class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th>名称</th><th>类型</th><th>余额（克）</th><th>操作</th></tr></thead><tbody><tr v-for="(e, rowIndex) in evidence" :key="e.id"><td class="row-number">{{(evidencePage-1)*20+rowIndex+1}}</td><td>{{e.label}}</td><td>{{e.parent_id ? '检材' : '原始证物'}}</td><td>{{e.balance}}</td><td><button class="link" :disabled="loading" @click="viewEvents(e.id)">查看流水</button></td></tr></tbody></table><p v-if="!evidence.length" class="empty">暂无证物</p></div><Pagination :page="evidencePage" :total="evidenceTotal" :loading="loading" @change="moveEvidence($event-evidencePage)" /><div v-if="selectedItem" class="detail"><h3>{{selectedItem.label}} · 重量流水</h3><ul><li v-for="event in events" :key="event.id">{{event.kind}} · {{event.delta}} 克 · {{event.reason}}</li></ul><Pagination :page="eventPage" :total="eventTotal" :loading="loading" @change="moveEvents($event-eventPage)" /><form v-if="!selectedItem.parent_id" v-show="can('evidence.write')" @submit.prevent="makeSample"><h3>登记分样</h3><label>检材名称<input v-model="sampleLabel" maxlength="200" required></label><label>重量（克）<input v-model="sampleWeight" type="number" min="0.000001" step="0.000001" required></label><label>操作依据<input v-model="sampleReason" maxlength="1000" required></label><button :disabled="loading">确认分样</button></form><CustodyPanel :key="selectedItem.id" :evidence="selectedItem" /><h3>盘点观测</h3><p class="muted">记录实测量和差异，账面余额不会自动调整。实际差异处理规则尚待确认。</p><form v-if="can('evidence.write')" @submit.prevent="submitInventory"><label>实测重量（克）<input v-model="observedWeight" type="number" min="0" step="0.000001" required></label><label>盘点说明<input v-model="inventoryNote" required maxlength="1000"></label><button :disabled="loading">记录盘点</button></form><div class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th>账面量（克）</th><th>实测量（克）</th><th>差异（克）</th><th>说明</th><th>盘点版本</th><th>操作人标识</th><th>记录时间</th><th>差异调查</th></tr></thead><tbody><tr v-for="(observation, rowIndex) in observations" :key="observation.id"><td class="row-number">{{(inventoryPage-1)*20+rowIndex+1}}</td><td>{{observation.book_weight}}</td><td>{{observation.observed_weight}}</td><td>{{observation.difference}}</td><td>{{observation.note}}</td><td>{{observation.evidence_version}}</td><td>{{observation.actor_id}}</td><td>{{formatTimestamp(observation.created_at)}}</td><td><button type="button" class="link" :disabled="loading" @click="showInvestigation(observation)">查看调查</button></td></tr></tbody></table><p v-if="!observations.length" class="empty">暂无盘点记录</p></div><Pagination :page="inventoryPage" :total="inventoryTotal" :loading="loading" @change="moveInventory($event-inventoryPage)" /><section v-if="selectedObservation && investigation" class="detail"><h3>差异调查（开发验证）</h3><p>盘点账面 {{selectedObservation.book_weight}} 克，实测 {{selectedObservation.observed_weight}} 克，差异 {{selectedObservation.difference}} 克。</p><p class="muted">调查复核仅记录说明，不代表批准调整或实际平账。生产审批权限尚未实现。</p><form v-if="!investigation.investigation" v-show="can('evidence.write')" @submit.prevent="startInvestigation"><label>启动原因<textarea v-model="investigationNote" required maxlength="1000"></textarea></label><button :disabled="loading">启动差异调查</button></form><template v-else><p>状态：{{({OPEN:'调查中',RETURNED:'已退回',PENDING_REVIEW:'待复核',REVIEWED:'说明已复核'} as Record<string,string>)[investigation.investigation.status] || '未知状态'}} · 调查人标识：{{investigation.investigation.investigator_id}}</p><form v-if="investigation.investigation.status!=='REVIEWED'" @submit.prevent="transitionInvestigation(investigation.investigation.status==='PENDING_REVIEW' ? 'REVIEW' : 'SUBMIT')"><label>调查或复核说明<textarea v-model="investigationNote" required maxlength="1000"></textarea></label><template v-if="investigation.investigation.status==='PENDING_REVIEW'"><p class="muted">须由调查提交人以外的本组织账号复核。</p><button :disabled="loading">确认复核说明</button> <button type="button" class="secondary" :disabled="loading || !investigationNote.trim()" @click="transitionInvestigation('RETURN')">退回补充</button></template><button v-else :disabled="loading">提交调查说明</button></form><h4>调查事件</h4><ul><li v-for="event in investigation.events.items" :key="event.id">{{event.action}} · {{event.actor_id}} · {{event.note}} · {{formatTimestamp(event.created_at)}}</li></ul><Pagination :page="investigationPage" :total="investigation.events.total" :loading="loading" :has-more="investigation.events.has_more" @change="moveInvestigation($event-investigationPage)" /></template></section></div></section><FormDialog v-if="creating" title="登记原始证物" :busy="loading" :error="error" @close="creating=false"><form @submit.prevent="searchCases"><label>查找可关联案件<input v-model="search" maxlength="100" placeholder="输入案件编号或名称"></label><button class="secondary" :disabled="loading">查找案件</button></form><p class="muted">下方列出当前查询的第 {{casePage}} 页。选择其他案件前请先查询或翻页。</p><Pagination :page="casePage" :total="caseTotal" :loading="loading" @change="moveCase($event-casePage)" /><form v-if="can('evidence.write')" @submit.prevent="submitCreate"><label>关联案件<select v-model="evidenceCase" required><option value="" disabled>选择案件</option><option v-for="c in cases" :key="c.id" :value="c.id">{{c.number}} · {{c.title}}</option></select></label><label>证物名称<input v-model="label" maxlength="200" required></label><label>初始重量（克）<input v-model="weight" type="number" min="0.000001" step="0.000001" required></label><label>登记依据<input v-model="reason" maxlength="1000" required></label><button :disabled="loading">登记证物</button></form></FormDialog></div>
</template>
